// SPDX-License-Identifier: MIT
pragma solidity 0.8.0;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/SCCS.sol";

contract SCCSTest is Test {
    SCCS token;
    address owner;
    address user = address(0x1);
    address mockPair = address(0x2);
    uint256 constant INITIAL_SUPPLY = 100_000_000_000 * 1e18;
    uint256 constant TEST_AMOUNT = 1000 * 1e18;

    function setUp() public {
        owner = address(this);
        token = new SCCS();

        // Initialize token with mock pair address
        token.setPairAddress(mockPair);
        token.transfer(user, TEST_AMOUNT * 100);
    }

    function testBurnInconsistency() public {
        uint256 initialUserBalance = token.balanceOf(user);
        uint256 initialTotalSupply = token.totalSupply();

        // Burn via transfer to pair (should apply fee)
        vm.prank(user);
        token.transfer(mockPair, TEST_AMOUNT);

        // Check results after transfer
        uint256 afterTransferUserBalance = token.balanceOf(user);
        uint256 afterTransferTotalSupply = token.totalSupply();
        uint256 afterTransferPairBalance = token.balanceOf(mockPair);

        // Burn via publicBurn (no fee applied)
        vm.prank(user);
        token.publicBurn(TEST_AMOUNT);

        // Check results after publicBurn
        uint256 finalUserBalance = token.balanceOf(user);
        uint256 finalTotalSupply = token.totalSupply();

        // Verify inconsistency:
        // 1. Transfer to pair resulted in fee+transfer with no net balance change
        // 2. publicBurn resulted in direct balance reduction
        assertTrue(
            finalTotalSupply < afterTransferTotalSupply, 
            "Burn functions should exhibit different burning behavior"
        );
    }
}
