        // ========== First Burn Method: Transfer to Pair ==========
        console2.log("--- PRE: Transfer to Pair Burn ---");
        uint256 preTransferUserBalance = token.balanceOf(user);
        uint256 preTransferTotalSupply = token.totalSupply();
        uint256 preTransferPairBalance = token.balanceOf(mockPair);
        console2.log("User Balance (Before):", preTransferUserBalance);
        console2.log("Total Supply (Before):", preTransferTotalSupply);
        console2.log("Pair Balance (Before):", preTransferPairBalance);
        console2.log("");

        // Execute transfer burn
        console2.log("--- Trigger Operation: Transfer to Pair ---");
        vm.prank(user);
        token.transfer(mockPair, TEST_AMOUNT);
        console2.log("Executed transfer(%d tokesn to pair)", TEST_AMOUNT);
        console2.log("");

        console2.log("--- POST: Transfer to Pair Burn ---");
        uint256 postTransferUserBalance = token.balanceOf(user);
        uint256 postTransferTotalSupply = token.totalSupply();
        uint256 postTransferPairBalance = token.balanceOf(mockPair);
        console2.log("User Balance (After):", postTransferUserBalance);
        console2.log("Total Supply (After):", postTransferTotalSupply);
        console2.log("Pair Balance (After):", postTransferPairBalance);

        // Calculate changes from first burn
        uint256 transferBurnUserLoss = preTransferUserBalance - postTransferUserBalance;
        uint256 transferBurnSupplyEffect = preTransferTotalSupply - postTransferTotalSupply;
        uint256 transferBurnPairGain = postTransferPairBalance - preTransferPairBalance;
        console2.log("");
        console2.log("[DIFF] Transfer-to-Pair Burn effect");
        console2.log("-> User Balance Change: -%d", transferBurnUserLoss);
        console2.log("-> Total Supply Change: -%d", transferBurnSupplyEffect);
        console2.log("-> Pair Balance Change: +%d", transferBurnPairGain);
        console2.log("");

        // ========== Second Burn Method: Public Burn ==========
        console2.log("--- PRE: Public Burn Method ---");
        uint256 prePublicBurnUserBalance = token.balanceOf(user);
        uint256 prePublicBurnTotalSupply = token.totalSupply();
        uint256 prePublicBurnPairBalance = token.balanceOf(mockPair);
        console2.log("User Balance (Before):", prePublicBurnUserBalance);
        console2.log("Total Supply (Before):", prePublicBurnTotalSupply);
        console2.log("Pair Balance (Before):", prePublicBurnPairBalance);
        console2.log("");

        // Execute public burn
        console2.log("--- Trigger Operation: Public Burn ---");
        vm.prank(user);
        token.publicBurn(TEST_AMOUNT);
        console2.log("Executed publicBurn(%d tokens)", TEST_AMOUNT);
        console2.log("");

        console2.log("--- POST: Public Burn Method ---");
        uint256 postPublicBurnUserBalance = token.balanceOf(user);
        uint256 postPublicBurnTotalSupply = token.totalSupply();
        uint256 postPublicBurnPairBalance = token.balanceOf(mockPair);
        console2.log("User Balance (After):", postPublicBurnUserBalance);
        console2.log("Total Supply (After):", postPublicBurnTotalSupply);
        console2.log("Pair Balance (After):", postPublicBurnPairBalance);

        // Calculate changes from second burn
        uint256 publicBurnUserLoss = prePublicBurnUserBalance - postPublicBurnUserBalance;
        uint256 publicBurnSupplyEffect = prePublicBurnTotalSupply - postPublicBurnTotalSupply;
        uint256 publicBurnPairGain = postPublicBurnPairBalance - prePublicBurnPairBalance;
        console2.log("");
        console2.log("[DIFF] Public Burn effect");
        console2.log("-> User Balance Change: -%d", publicBurnUserLoss);
        console2.log("-> Total Supply Change: -%d", publicBurnSupplyEffect);
        console2.log("-> Pair Balance Change: +%d", publicBurnPairGain);
        console2.log("");

        // ========== Differential Verification ==========
        console2.log("--- Vulnerability Check ---");
        console2.log("Comparing burn method effects (transfer-to-pair vs publicBurn):");
        bool inconsistentUserBalance = transferBurnUserLoss != publicBurnUserLoss;
        bool inconsistentSupply = transferBurnSupplyEffect != publicBurnSupplyEffect;
        bool inconsistentPair = transferBurnPairGain != publicBurnPairGain;

        console2.log("• User Balance Consistency?: %s", !inconsistentUserBalance ? "SAME" : "DIFFERENT");
        console2.log("• Total Supply Consistency?: %s", !inconsistentSupply ? "SAME" : "DIFFERENT");
        console2.log("• Pair Balance Consistency?: %s", !inconsistentPair ? "SAME" : "DIFFERENT");

        // Final verdict (log once only)
        if (inconsistentUserBalance || inconsistentSupply || inconsistentPair) {
            console2.log("Vulnerability Exists: Burn methods exhibit inconsistent state changes");
        } else {
            console2.log("Vulnerability not Exist: Both burn methods produce identical state changes");
        }
    }
}
